/// THE WIRE'S OWN SOURCE SCAN (javap `Level.hasNeighborSignal` pc
/// 0-33 the `Direction.values()` loop the `getSignal(pos.relative
/// (dir), dir) != 0` read wears — the SOURCES the loop's nonzero
/// verdict the client's kind-only vocabulary answers: the lever's
/// `powered ? 15 : 0` fold, the button's press walk the ON kind's
/// own 15 arms, the plate's powered kinds the sensor rows speak).
/// THE WIRE'S OWN EXCLUSION (the shouldSignal re-entrancy guard the
/// getSignal walk's own gate keeps — the wire cell's verdict walk
/// the OTHER WIRES never reads: the source-only scan the component
/// BFS consults, the self-feed loop the guard's own law refuses).
pub fn wire_sources_near(world: &World, x: i32, y: i32, z: i32) -> bool {
    (world.get(x, y + 1, z) == LEVER_ON)
        || (world.get(x, y - 1, z) == LEVER_ON)
        || (world.get(x + 1, y, z) == LEVER_ON)
        || (world.get(x - 1, y, z) == LEVER_ON)
        || (world.get(x, y, z + 1) == LEVER_ON)
        || (world.get(x, y, z - 1) == LEVER_ON)
        || button_powered(world.get(x, y + 1, z))
        || button_powered(world.get(x, y - 1, z))
        || button_powered(world.get(x + 1, y, z))
        || button_powered(world.get(x - 1, y, z))
        || button_powered(world.get(x, y, z + 1))
        || button_powered(world.get(x, y, z - 1))
        || plate_powered(world.get(x, y + 1, z))
        || plate_powered(world.get(x, y - 1, z))
        || plate_powered(world.get(x + 1, y, z))
        || plate_powered(world.get(x - 1, y, z))
        || plate_powered(world.get(x, y, z + 1))
        || plate_powered(world.get(x, y, z - 1))
        // THE TORCH'S OWN SOURCE ARMS (the autopush-666 round — the
        // getSignal walk's d != UP verdict the lit kind's own 15 the
        // five arms wear: the torch ABOVE the wire cell the UP arm the
        // dark 0 keeps, the four horizontals AND the below arm the lit
        // kind answers — the [`torch_sources_near`] walk the same
        // helper the door's own read serves)
        || torch_sources_near(world, x, y, z)
        // THE WALL TORCH'S OWN SOURCE ARMS (the autopush-667 round —
        // the getSignal walk's direction == FACING verdict the
        // per-torch compare the variant decode serves: the torch at
        // +step the FACING arm refuses, the other five arms the lit
        // kind answers — the [`wall_torch_sources_near`] walk the
        // door's own read the same helper serves)
        || wall_torch_sources_near(world, x, y, z)
}

/// THE WIRE'S OWN COMPONENT WALK (the graded POWER lane the
/// autopush-673 round banks — the DEFAULT evaluator's own walk the
/// RedStoneWireBlock.updatePowerStrength + the
/// DefaultRedstoneWireEvaluator.calculateTargetChangeset pair the
/// binary ANY-source verdict retires: the wire's power the neighbor
/// graph the same-level run carries, the decay the 15-block run the
/// vanilla's own math wears — the source-adjacent cell the 15 wears,
/// the wire neighbor the `power - 1` offer the rung answers, the
/// max-plus fixpoint the relaxation's own pass loop keeps). THE
/// SEEDS THE CALLER BANKS (the changed cell + its six neighbors the
/// attach walk's own scope keeps — the
/// updateNeighborsOfNeighboringWires walk pc 0-118 the adjacent
/// wires the re-evaluate arms speak): the flood the wire cells
/// walks (the 4-horizontal same-level steps the first lane keeps —
/// the up/down climbing the future lane's own walk serves), the
/// per-cell power the fixpoint's unique verdict answers (the LEAST
/// fixpoint the iteration order never reads — the max-plus algebra
/// the same answer the any walk keeps, the component's own length
/// the pass cap bounds), the flip list the (pos, kind) rows the
/// caller's setBlock wears (the same-kind rows the no-op setBlock
/// the honest list keeps — the caller's own remesh the changed
/// pixels alone answers). THE PURE WALK (no &mut — the borrow
/// discipline the attach walks' own read-first law keeps: the
/// caller applies the flips the remesh answers).
pub fn wire_component_flips(
    world: &World,
    seeds: &[(i32, i32, i32)],
) -> Vec<((i32, i32, i32), u16)> {
    let mut seen: std::collections::HashSet<(i32, i32, i32)> = std::collections::HashSet::new();
    let mut queue: std::collections::VecDeque<(i32, i32, i32)> = std::collections::VecDeque::new();
    for &(x, y, z) in seeds {
        if is_redstone_wire(world.get(x, y, z)) {
            queue.push_back((x, y, z));
        }
    }
    let mut out: Vec<((i32, i32, i32), u16)> = Vec::new();
    while let Some(start) = queue.pop_front() {
        // THE CONSUMED SEED'S OWN SKIP (the earlier component's flood
        // the seed already banks — the same-component seeds the ONE
        // verdict the shared walk keeps: the pop-time insert the
        // dedupe law wears, the component the flood's own growth
        // answers)
        if !seen.insert(start) {
            continue;
        }
        // THE COMPONENT'S OWN FLOOD (the same-level run the 4-horizontal
        // steps walk — the seen set the re-fire the dedupe keeps, the
        // index map the relaxation's own neighbor reads the seat wears)
        let mut component: Vec<(i32, i32, i32)> = vec![start];
        let mut index: std::collections::HashMap<(i32, i32, i32), usize> =
            std::collections::HashMap::new();
        index.insert(start, 0);
        let mut ci = 0usize;
        while ci < component.len() {
            let (x, y, z) = component[ci];
            ci += 1;
            for (nx, ny, nz) in
                [(x + 1, y, z), (x - 1, y, z), (x, y, z + 1), (x, y, z - 1)]
            {
                if !is_redstone_wire(world.get(nx, ny, nz)) {
                    continue;
                }
                if !seen.insert((nx, ny, nz)) {
                    continue;
                }
                index.insert((nx, ny, nz), component.len());
                component.push((nx, ny, nz));
            }
        }
        // THE POWER'S OWN SEEDS (the source-adjacent cells the 15
        // wear — the wire_sources_near scan the hasNeighborSignal
        // subset the lever/button/plate/torch arms answer) + THE
        // RELAXATION'S OWN FIXPOINT (the offer the max-plus fold
        // banks: the same-component neighbor's power the -1 decay
        // the rung speaks, the pass loop the no-change beat the
        // convergence answers — the LEAST fixpoint the iteration
        // order never reads, the component's own hop count the
        // pass cap bounds)
        let mut powers: Vec<u8> = component
            .iter()
            .map(|&(x, y, z)| {
                if wire_sources_near(world, x, y, z) {
                    15
                } else {
                    0
                }
            })
            .collect();
        for _ in 0..=component.len() {
            let mut changed = false;
            for i in 0..component.len() {
                let (x, y, z) = component[i];
                let mut offer = powers[i];
                for (nx, ny, nz) in
                    [(x + 1, y, z), (x - 1, y, z), (x, y, z + 1), (x, y, z - 1)]
                {
                    if let Some(&j) = index.get(&(nx, ny, nz)) {
                        let candidate = powers[j].saturating_sub(1);
                        if candidate > offer {
                            offer = candidate;
                        }
                    }
                }
                if offer > powers[i] {
                    powers[i] = offer;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        // THE LADDER'S OWN TARGETS (the per-cell power the kind seat
        // the inverse read answers — the 0 the plain row keeps, the
        // 15 the _on kind wears, the middle rungs the `_pNN` rows
        // speak): the cells the current kind the flip list banks
        for (i, cell) in component.iter().enumerate() {
            let target = wire_kind_for_power(powers[i]);
            let kind = world.get(cell.0, cell.1, cell.2);
            if kind != target {
                out.push((*cell, target));
            }
        }
        // the unvisited neighbors the NEXT component's seeds keep —
        // the queue the flood already drained: the seeds the caller
        // banks only fire once each (the seen set the shared law
        // keeps)
    }
    out
}

/// THE LAMP'S OWN VERDICT WALK (the autopush-672 round — the consumer
/// block the attach lanes' own consumer arm serves): the seeds' own
/// cells AND their six the lamp seats the scan answers (the placed
/// lamp the seed cell itself the placement verdict reads, the wire
/// flips' own cells the run's tail lamps the flood's own reach arms
/// — the vanilla neighborChanged broadcast the changed cell's own
/// six the radius keeps), the `lit == signal` verdict the
/// state-NEEDS-CHANGE lamp the flip banks (the state-correct pair
/// the quiet keep wears), the dedup the seen set the repeat seeds
/// refuse, the sorted scan the deterministic order the callers'
/// asserts keep, the PURE read the caller's own set walk the apply
/// serves (the walk the world never mutates).
pub fn redstone_lamp_flips(
    world: &World,
    seeds: &[(i32, i32, i32)],
) -> Vec<((i32, i32, i32), u16)> {
    let mut out: Vec<((i32, i32, i32), u16)> = Vec::new();
    let mut seen: std::collections::HashSet<(i32, i32, i32)> =
        std::collections::HashSet::new();
    for &(sx, sy, sz) in seeds {
        let mut cells = [
            (sx, sy, sz),
            (sx, sy - 1, sz),
            (sx, sy + 1, sz),
            (sx, sy, sz - 1),
            (sx, sy, sz + 1),
            (sx - 1, sy, sz),
            (sx + 1, sy, sz),
        ];
        cells.sort();
        for (x, y, z) in cells.iter() {
            if !seen.insert((*x, *y, *z)) {
                continue;
            }
            let kind = world.get(*x, *y, *z);
            if !is_redstone_lamp(kind) {
                continue;
            }
            let lit = redstone_lamp_lit(kind);
            if redstone_signal_at(world, *x, *y, *z) != lit {
                if let Some(flip) = redstone_lamp_toggled(kind) {
                    out.push(((*x, *y, *z), flip));
                }
            }
        }
    }
    out
}

