#[inline]
pub fn stairs_facing_delta(facing: u8) -> (i32, i32) {
    match facing & 0b11 {
        STAIRS_FACING_EAST => (1, 0),
        STAIRS_FACING_SOUTH => (0, 1),
        STAIRS_FACING_WEST => (-1, 0),
        _ => (0, -1),
    }
}

/// THE STAIRS FACING'S OWN QUARTER TURNS (the counter-clockwise and
