    fn bamboo_height_below(&self, x: i32, y: i32, z: i32) -> u32 {
        let mut count = 0u32;
        while count < 16 && self.get(x, y - count as i32 - 1, z) == BAMBOO {
            count += 1;
        }
        count
    }

