    fn portal_cell_axis_x(&self, pos: (i32, i32, i32)) -> bool {
        if let Some(&x) = self.portal_axis.get(&pos) {
            return x;
        }
        self.get(pos.0 - 1, pos.1, pos.2) == NETHER_PORTAL
            || self.get(pos.0 + 1, pos.1, pos.2) == NETHER_PORTAL
    }

    /// THE PORTAL'S OWN UPDATE-SHAPE DOUSE (javap NetherPortalBlock.
